from dataclasses import dataclass, field
from enum import Enum

class State(Enum):
    OBSERVED = "observed"
    CORRELATED = "correlated"
    ESCALATED = "escalated"
    CLOSED = "closed"

@dataclass
class Record:
    event_id: str
    state: State = State.OBSERVED
    evidence: list[str] = field(default_factory=list)
    reason: str = "created"

def advance(record, signal):
    allowed = {
        (State.OBSERVED, "correlate"): State.CORRELATED,
        (State.CORRELATED, "escalate"): State.ESCALATED,
        (State.ESCALATED, "close"): State.CLOSED,
    }
    target = allowed.get((record.state, signal))
    if target is None:
        raise ValueError(f"invalid transition: {record.state.value} -> {signal}")
    if signal != "correlate" and not record.evidence:
        raise ValueError("transition requires retained evidence")
    record.state, record.reason = target, signal
    return record

